int n, k;

// compare function for qsort
int cmp(const void *a, const void *b) {
    long long la = *(const long long*)a;
    long long lb = *(const long long*)b;
    if (la < lb) return -1;
    if (la > lb) return 1;
    return 0;
}

// check if we can achieve at least k visible buildings with given max height increase limit
int can(long long limit) {
    // we try to greedily make buildings visible by increasing them when necessary
    long long max_so_far = -1;
    int visible = 0;
    long long cost = 0;

    for (int i = 0; i < n; i++) {
        long long h = a[i];
        if (h > max_so_far) {
            visible++;
            max_so_far = h;
        } else {
            // need to increase to be visible: must be > max_so_far
            long long needed = max_so_far + 1 - h;
            if (needed > limit) {
                // cannot increase enough, skip this building (leave it hidden)
                continue;
            }
            cost += needed;
            if (cost > limit) return 0;
            visible++;
            max_so_far = max_so_far + 1;
        }
    }
    return visible >= k;
}

int main() {
    scanf("%d %d", &n, &k);
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    // binary search on the answer
    long long lo = 0, hi = 1e18, ans = 1e18;
    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;
        if (can(mid)) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

