#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef long long ll;

static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    ll a[20];
    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);

    ll ans = LLONG_MAX;

    /* Enumerate subsets of buildings to be visible.
       Building 0 is always visible without any operation, so any valid subset
       must contain at least K buildings in total, counting naturally visible
       after modifications according to the chosen forced-visible set.

       For a chosen subset, process from left to right:
       keep current maximum height mx.
       If building i is chosen, raise it to at least mx+1 if necessary.
       Otherwise leave it as is.
       This gives the minimum cost for that subset.
    */
    int total = 1 << N;
    for (int mask = 0; mask < total; mask++) {
        int cnt = 0;
        for (int i = 0; i < N; i++) {
            if (mask & (1 << i)) cnt++;
        }
        if (cnt < K) continue;

        ll cost = 0;
        ll mx = 0;
        int visible = 0;

        for (int i = 0; i < N; i++) {
            ll h = a[i];
            if (mask & (1 << i)) {
                if (h <= mx) {
                    cost += (mx + 1 - h);
                    h = mx + 1;
                }
            }
            if (h > mx) visible++;
            if (h > mx) mx = h;
        }

        if (visible >= K) ans = minll(ans, cost);
    }

    printf("%lld\n", ans);
    return 0;
}

