    vector<int64> dp(K + 1, INF);
    dp[0] = 0;

    for (int i = 0; i < N; i++) {
        vector<int64> ndp(K + 1, INF);
        for (int j = 0; j <= K; j++) {
            if (dp[j] == INF) continue;
            // case: building i not visible
            ndp[j] = min(ndp[j], dp[j]);
        }
        // case: make building i visible
        // We need to consider the last visible height.
        // Instead, re-do dp over j with tracking last height.
        // We'll store best cost for each j and last height.
    }

    // Alternative: DP with last height
    // dp[i][j] = min cost with last visible = i, j visible
    vector<vector<int64>> dp2(N, vector<int64>(K + 1, INF));
    for (int i = 0; i < N; i++) {
        dp2[i][1] = 0; // make it visible as first by not raising? Actually it's already visible if first
    }

    for (int i = 0; i < N; i++) {
        for (int j = 1; j <= K; j++) {
            if (dp2[i][j] == INF) continue;
            for (int nxt = i + 1; nxt < N; nxt++) {
                int64 cost = 0;
                if (a[nxt] <= a[i]) cost = a[i] + 1 - a[nxt];
                if (j + 1 <= K) {
                    dp2[nxt][j + 1] = min(dp2[nxt][j + 1], dp2[i][j] + cost);
                }
            }
        }
    }

    int64 ans = INF;
    for (int i = 0; i < N; i++) {
        ans = min(ans, dp2[i][K]);
    }
    cout << ans << "\n";

    return 0;
