public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        long[] h = new long[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            h[i] = Long.parseLong(st.nextToken());
        }

        final long INF = Long.MAX_VALUE / 2;
        long[][] dp = new long[N][K + 1];
        for (int i = 0; i < N; i++) {
            Arrays.fill(dp[i], INF);
            dp[i][1] = 0;
        }

        for (int i = 0; i < N; i++) {
            for (int j = 1; j <= K; j++) {
                if (dp[i][j] == INF) continue;
                // try to make i+1 visible next
                for (int next = i + 1; next < N; next++) {
                    long cost = 0;
                    long neededHeight = h[i];
                    for (int m = i + 1; m < next; m++) {
                        if (h[m] >= neededHeight) {
                            cost += h[m] - (neededHeight - 1);
                        }
                    }
                    if (h[next] <= neededHeight) {
                        cost += neededHeight + 1 - h[next];
                    }
                    if (j + 1 <= K) {
                        dp[next][j + 1] = Math.min(dp[next][j + 1], dp[i][j] + cost);
                    }
                }
            }
        }

        long ans = INF;
        for (int i = 0; i < N; i++) {
            ans = Math.min(ans, dp[i][K]);
        }
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int K = fs.nextInt();
        long[] a = new long[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextLong();

        long ans = Long.MAX_VALUE;

        // Enumerate subsets of buildings to be visible.
        // Building 0 is always visible from the left, so we only need subsets with size >= K
        // among all buildings, respecting that selected buildings are raised minimally.
        for (int mask = 0; mask < (1 << N); mask++) {
            if (Integer.bitCount(mask) < K) continue;

            long cost = 0;
            long maxHeight = 0;

            for (int i = 0; i < N; i++) {
                if ((mask & (1 << i)) != 0) {
                    // This building must be visible, so its height must be > current maxHeight
                    if (a[i] > maxHeight) {
                        maxHeight = a[i];
                    } else {
                        cost += (maxHeight + 1 - a[i]);
                        maxHeight = maxHeight + 1;
                    }
                } else {
                    // Not required to be visible; keep as is, but it still affects later visibility
                    maxHeight = Math.max(maxHeight, a[i]);
                }
            }

            ans = Math.min(ans, cost);
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
